<?php
session_start();if(!isset($_SESSION['user_id'])){header('Location: login.html');exit;}require __DIR__.'/db.php';require __DIR__.'/artwork-common.php';$uid=(int)$_SESSION['user_id'];if(!artworkIsStudent($conn,$uid)){http_response_code(403);exit('Student only');}$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT);if(!$id){http_response_code(400);exit('Invalid artwork');}
$s=$conn->prepare('SELECT title,status,created_at,reviewed_at,rejection_reason FROM artworks WHERE artwork_id=? AND user_id=?');$s->bind_param('ii',$id,$uid);$s->execute();$art=$s->get_result()->fetch_assoc();$s->close();if(!$art){http_response_code(404);exit('Artwork not found');}
$s=$conn->prepare('SELECT action,details,created_at FROM artwork_status_history WHERE artwork_id=? ORDER BY created_at DESC, history_id DESC');$s->bind_param('i',$id);$s->execute();$events=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Review History | MIRA</title><link rel="stylesheet" href="artwork-workflow.css"><link rel="stylesheet" href="submission-tracking.css"><link rel="stylesheet" href="mira-student-nav.css?v=2"><script src="theme.js" defer></script><link rel="stylesheet" href="mira-design-system.css?v=1">
</head><body class="mira-workflow"><?php require __DIR__.'/mira-student-nav.php'; ?><main class="workflow-wrap"><div class="workflow-heading"><p class="overline">SUBMISSION HISTORY</p><h1><?= artworkEscape($art['title']) ?></h1><p>Current status: <strong><?= artworkEscape(ucfirst($art['status'])) ?></strong></p></div><section class="tracking-timeline"><article class="tracking-event"><b>Originally submitted</b><p><?= artworkEscape(date('M j, Y g:i A',strtotime($art['created_at']))) ?></p></article><?php foreach(array_reverse($events) as $event): ?><article class="tracking-event"><b><?= artworkEscape(ucfirst(str_replace('_',' ',$event['action']))) ?></b><p><?= artworkEscape(date('M j, Y g:i A',strtotime($event['created_at']))) ?></p><?php if($event['details']): ?><p><?= artworkEscape($event['details']) ?></p><?php endif; ?></article><?php endforeach; ?><?php if(!$events && $art['reviewed_at']): ?><article class="tracking-event"><b><?= artworkEscape(ucfirst($art['status'])) ?> (earlier review)</b><p><?= artworkEscape(date('M j, Y g:i A',strtotime($art['reviewed_at']))) ?></p><?php if($art['rejection_reason']): ?><p><?= artworkEscape($art['rejection_reason']) ?></p><?php endif; ?></article><?php endif; ?></section><p><a class="outline-btn" href="my-artworks.php">← Back to submissions</a></p></main></body></html>
